CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `projeto`.`zero_gap` AS with `gap_por_cargo` as (select `projeto`.`fato_mercado_salarios_tech`.`cargo` AS `cargo`,`projeto`.`fato_mercado_salarios_tech`.`senioridade` AS `senioridade`,count((case when (`projeto`.`fato_mercado_salarios_tech`.`genero` = 'Feminino') then 1 end)) AS `qtd_mulheres`,avg((case when (`projeto`.`fato_mercado_salarios_tech`.`genero` = 'Masculino') then `projeto`.`fato_mercado_salarios_tech`.`salario_mensal_brl` end)) AS `sal_medio_masc`,avg((case when (`projeto`.`fato_mercado_salarios_tech`.`genero` = 'Feminino') then `projeto`.`fato_mercado_salarios_tech`.`salario_mensal_brl` end)) AS `sal_medio_fem` from `projeto`.`fato_mercado_salarios_tech` group by `projeto`.`fato_mercado_salarios_tech`.`cargo`,`projeto`.`fato_mercado_salarios_tech`.`senioridade`) select `gap_por_cargo`.`cargo` AS `cargo`,`gap_por_cargo`.`senioridade` AS `senioridade`,`gap_por_cargo`.`qtd_mulheres` AS `qtd_mulheres`,round(`gap_por_cargo`.`sal_medio_masc`,2) AS `sal_referencia_masculino`,round(`gap_por_cargo`.`sal_medio_fem`,2) AS `sal_atual_feminino`,round((`gap_por_cargo`.`sal_medio_masc` - `gap_por_cargo`.`sal_medio_fem`),2) AS `diferenca_unitaria_brl`,round((((`gap_por_cargo`.`qtd_mulheres` * (`gap_por_cargo`.`sal_medio_masc` - `gap_por_cargo`.`sal_medio_fem`)) * 13.33) * 1.40),2) AS `orcamento_anual_com_encargos_brl` from `gap_por_cargo` where ((`gap_por_cargo`.`sal_medio_masc` - `gap_por_cargo`.`sal_medio_fem`) > 0) order by round((((`gap_por_cargo`.`qtd_mulheres` * (`gap_por_cargo`.`sal_medio_masc` - `gap_por_cargo`.`sal_medio_fem`)) * 13.33) * 1.40),2) desc